#define _GNU_SOURCE

#include <errno.h>
#include <limits.h>
#include <stdlib.h>
#include <sys/syscall.h>
#include <sys/types.h>
#include <unistd.h>

/*
 * Lean 4.22 resolves its installation through /proc/<getpid()>/exe.  The
 * audit sandbox exposes host /proc while getpid() returns a namespace PID.
 * Return the host PID exposed by /proc/self so Lean observes a consistent
 * procfs.  Fall back to the real system call if procfs cannot be read.
 */
pid_t getpid(void) {
    char target[64];
    ssize_t length = readlink("/proc/self", target, sizeof(target) - 1);
    if (length > 0 && length < (ssize_t)sizeof(target)) {
        target[length] = '\0';
        errno = 0;
        char *end = NULL;
        long value = strtol(target, &end, 10);
        if (errno == 0 && end != target && *end == '\0' && value > 0 && value <= INT_MAX) {
            return (pid_t)value;
        }
    }
    return (pid_t)syscall(SYS_getpid);
}

